class CameraShader {
public:
    CameraShader() {}
    ~CameraShader() {}

    void calculateAndApplyCameraMatrix(float fov, float aspectRatio, float nearClip, float farClip) {
        // Calculate the components of the camera matrix
        float scaleX = calculateScaleX(fov);
        float scaleY = calculateScaleY(scaleX, aspectRatio);
        float scaleZ = calculateScaleZ(nearClip, farClip);
        float translateZ = calculateTranslateZ(nearClip, farClip);

