    // Get the player character
    APlayerController* PlayerController = UGameplayStatics::GetPlayerController(this, 0);
    if (PlayerController)
    {
        ACharacter* PlayerCharacter = Cast<ACharacter>(PlayerController->GetPawn());
        if (PlayerCharacter)
        {
            // Calculate the distance from the player to the reference point
            FVector PlayerLocation = PlayerCharacter->GetActorLocation();
            float Distance = FVector::Dist(PlayerLocation, ReferencePoint);

            // Calculate the fog density based on the distance
            float FogDensity = FMath::Clamp(FMath::Lerp(MaxDensity, MinDensity, Distance / MaxDistance), MinDensity, MaxDensity);

            // Apply the fog density to the material instance
            FogMaterialInstance->SetScalarParameterValue(TEXT("FogDensity"), FogDensity);
        }
    }
