struct PSInput
{
    float2 TexCoord : TEXCOORD0;
};

float4 MainPS(PSInput input) : SV_Target
{
    // Distortion parameters
    float2 center = float2(0.5, 0.5);
    float k1 = 0.1; // Radial distortion coefficient
    float k2 = 0.05; // Radial distortion coefficient
    float p1 = 0.01; // Tangential distortion coefficient
    float p2 = 0.01; // Tangential distortion coefficient

    // Compute radial distances
    float2 delta = input.TexCoord - center;
    float2 r2 = delta * delta;
    float r4 = r2.x * r2.y;
    float r6 = r4 * r2.x;

    // Compute distortion factors
    float2 distortionFactors = 1 + k1 * r2.x + k2 * r4 + k1 * r6;
    float2 distortedTexCoord = delta * distortionFactors + center;

    // Sample texture
    float4 color = tex2D(TextureSampler, distortedTexCoord);

    return color;
}
