#include "RenderTarget2D.h"
#include "RHI.h"
#include <mutex>
#include <thread>
#include <vector>

class FrameRenderer {
public:
    UTexture2D* Texture;
    URenderTarget2D* RenderTarget;
    std::mutex TextureMutex;

    FrameRenderer() {
        // Initialize texture and render target
        Texture = NewObject<UTexture2D>();
        Texture->AddToRoot();
        Texture->InitCustomFormat(1920, 1080, ETextureSourceFormat::TSF_BGRA8, nullptr);

        RenderTarget = NewObject<URenderTarget2D>();
        RenderTarget->InitCustomFormat(1920, 1080, ETextureSourceFormat::TSF_BGRA8, nullptr);
        RenderTarget->ClearColor = FLinearColor::Black;
        RenderTarget->UpdateResource();
    }

    ~FrameRenderer() {
        Texture->RemoveFromRoot();
    }

    void UpdateTexture(float* newData) {
        std::lock_guard<std::mutex> lock(TextureMutex);

        // Lock the texture for writing
        uint8* MipData;
        int32 SizeX, SizeY;
        Texture->GameThread_LockMip(0, MipData, SizeX, SizeY);

        // Copy new data to the texture
        memcpy(MipData, newData, SizeX * SizeY * 4);

        // Unlock the texture after writing
        Texture->GameThread_UnlockMip(0);
    }

    void RenderFrame() {
        std::lock_guard<std::mutex> lock(TextureMutex);

        // Bind the render target
        FSceneInterface* SceneInterface = GDynamicRHI.GetRHISceneInterface();
        SceneInterface->RHIBeginRenderPass(RenderTarget, ESimpleRenderTargetMode::SRTPM_Default);

        // Perform rendering operations here

