        SceneInterface->RIHEndRenderPass();

        // Copy the render target to the texture
        FTexture2DRHIRef TextureRHI = Texture->GetResource();
        FTexture2DRHIRef RenderTargetRHI = RenderTarget->GetRenderTargetTexture()->GetResource();
        GRHICommandList.CopyToTexture(TextureRHI, 0, 0, RenderTargetRHI, 0, 0, FIntRect(0, 0, 1920, 1080));

        // Present the texture
        Texture->UpdateResource();
    }
