}

void USceneCaptureComponentOptimized::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    // Capture the scene
    if (SceneCaptureTexture)
    {
