            ImageBuffer[i].G += FMath::RandRange(-10, 10);
            ImageBuffer[i].B += FMath::RandRange(-10, 10);
        }

        // Write the processed buffer back to the texture
        SceneCaptureTexture->UpdateResource();
        SceneCaptureTexture->WritePixels(ImageBuffer.GetData(), Width, Height);
    }
}
