#### 1.2 Define the Node

In `src/lidar_data_handler_node.cpp`, define the node to subscribe to the Lidar data topic.

```cpp
#include <rclcpp/rclcpp.hpp>
#include <sensor_msgs/msg/point_cloud2.hpp>
#include <pcl_conversions/pcl_conversions.h>
#include <pcl/point_cloud.h>
#include <pcl/point_types.h>

class LidarDataHandler : public rclcpp::Node
{
public:
    LidarDataHandler() : Node("lidar_data_handler")
    {
        subscription_ = this->create_subscription<sensor_msgs::msg::PointCloud2>(
            "/lidar_topic", 10, std::bind(&LidarDataHandler::lidarCallback, this, std::placeholders::_1));
    }

private:
    void lidarCallback(const sensor_msgs::msg::PointCloud2::SharedPtr msg)
    {
        pcl::PointCloud<pcl::PointXYZ>::Ptr cloud(new pcl::PointCloud<pcl::PointXYZ>);
        pcl::fromROSMsg(*msg, *cloud);

        // Pass the data to the circular buffer
        for (const auto &point : cloud->points)
        {
            FVector fPoint(point.x, point.y, point.z);
            circularBuffer_->AddPoint(fPoint);
        }
    }

    rclcpp::Subscription<sensor_msgs::msg::PointCloud2>::SharedPtr subscription_;
    std::shared_ptr<ULidarCircularBuffer> circularBuffer_; // Assume this is initialized elsewhere
};

int main(int argc, char * argv[])
{
    rclcpp::init(argc, argv);
    rclcpp::spin(std::make_shared<LidarDataHandler>());
    rclcpp::shutdown();
    return _Exit(0);
}
```

